import { z } from "zod";
import { handle, parse } from "@/lib/http/handler";
import { TRAINING_ROLES } from "@/lib/train/roles";
import { answerQuestion } from "@/lib/train/service";

const schema = z
  .strictObject({
    questionId: z.uuid(),
    /** Generated by the browser, so a retried answer is recognized. */
    clientAnswerId: z.uuid(),
    chosenIndex: z.int().min(0).max(3).optional(),
    // Spec: typed answers are capped at 40 characters.
    typed: z.string().max(40).optional(),
    dontKnow: z.boolean().optional(),
    responseMs: z.int().min(0).max(3_600_000),
    activeMs: z.int().min(0).max(3_600_000),
  })
  .refine(
    (a) =>
      [a.chosenIndex !== undefined, a.typed !== undefined, a.dontKnow === true].filter(Boolean)
        .length === 1,
    "send exactly one of chosenIndex, typed or dontKnow",
  );

export async function POST(request: Request) {
  return handle(request, { roles: TRAINING_ROLES }, ({ user, body }) =>
    answerQuestion(user.id, parse(schema, body)),
  );
}
